local passed=0
local function test(name,fn) fn(); passed=passed+1; print("PASS "..name) end
test("confirmed opening observes 2.5 seconds before offering",function() local f=fixture(); f:start(); f:advance(2.7); eq(f.offers,0); f:advance(3.2); eq(f.offers,1) end)
test("unreachable highest is replaced by partner-reachable opener",function() local f=fixture(); f.own.items[1]=f:item("Huge",1000); f:start(); f:advance(3.2); eq(f.offers,1); assert(f:total()<1000) end)
test("opponent-first visible offer skips speculative opener",function() local f=fixture(); f:start(); f:advance(1); eq(f.offers,0); f:setTheir({f.partnerInv.items[2]}); f:advance(1.5); eq(f.offers,0); f:advance(4); assert(f:total()<=85 and f:total()>0); eq(f.accepts,0) end)
test("visible unknown offer during observe never becomes zero or an opener",function() local f=fixture(); f:start(); f:advance(1); f:setTheir({{id="Unknown",name="Unknown",qty=1}}); f:advance(4); eq(f.offers,0); eq(f.declines,0); f:advance(62); eq(f.declines,1) end)
test("no reachable opener still expires empty at twelve seconds",function() local f=fixture(); f.own.items={f:item("Huge",10000)}; f:start(); f:advance(4); eq(f.offers,0); f:advance(13); eq(f.declines,1) end)
test("missing own inventory still handles accepted empty",function() local f=fixture(); f.scanner.getOwnInventory=function() return nil,"unavailable" end; f:start(); f:advance(1); f.accepted.Visible=true; f:advance(1.3); eq(f.offers,0); eq(f.declines,1) end)
test("manual own Accepted freezes voluntary offer changes",function() local f=fixture(); f:start(); f:advance(1); f:setTheir({f.partnerInv.items[2]}); f:advance(4); local before=f.offers; local own=f.root.children.YourOffer; node("Accepted","Frame",own,{Visible=true}); f:advance(20); eq(f.offers,before); eq(f.accepts,0) end)
test("opponent change invalidates unsafe manual acceptance by safe decline",function() local f=fixture(); f:start(); f:advance(3.2); local own=f.root.children.YourOffer; node("Accepted","Frame",own,{Visible=true}); f:setTheir({f.partnerInv.items[2]}); f:advance(4.5); eq(f.declines,1); eq(f.offers,1) end)
test("stop during inventory yield prevents later offers",function() local f=fixture(); f.ownDelay=2; local c=f:start(); f:advance(1); c.stop(); f:advance(5); eq(f.offers,0) end)
test("same root close-reopen during observe invalidates old trade",function() local f=fixture(); f:start(); f:advance(1); f.root.Visible=false; f.root:GetPropertyChangedSignal("Visible"):Fire(); f.root.Visible=true; f:advance(4); eq(f.offers,0) end)
test("price expiry during observation closes safely",function() local f=fixture(); f:start(); f:advance(1); f.profile.isFresh=function() return false end; f:advance(2); eq(f.offers,0); eq(f.declines,1) end)
test("partner leaving during observe prevents opener",function() local f=fixture(); f:start(); f:advance(1); f.target.Parent=nil; f:advance(4); eq(f.offers,0) end)
test("missing local Accepted indicator blocks mutations but not timeout",function() local f=fixture(); f.root.children.YourOffer.children.Accepted=nil; f:start(); f:advance(4); eq(f.offers,0); f:advance(13); eq(f.declines,1) end)
test("manual approval is invalidated by even a still-profitable changed offer",function() local f=fixture(); f:start(); f:advance(1); f:setTheir({f.partnerInv.items[2]}); f:advance(4); f.root.children.YourOffer.children.Accepted.Visible=true; f:advance(4.5); f:setTheir({f.partnerInv.items[1]}); f:advance(5); eq(f.declines,1) end)
test("missing partner record from startup still expires empty",function() local f=fixture(); f.scanner.getRecord=function() return nil end; f:start(); f:advance(4); eq(f.offers,0); f:advance(13); eq(f.declines,1) end)
test("manual acceptance just after our verified rebalance is not a changed offer",function() local f=fixture(); f.onOffer=function() f.task.spawn(function() f.task.wait(.17); f.root.children.YourOffer.children.Accepted.Visible=true end) end; f:start(); f:advance(1); f:setTheir({f.partnerInv.items[2]}); f:advance(5); eq(f.declines,0); assert(f.offers>0) end)
test("native unaccept reset cannot erase prior approval signature",function() local f=fixture(); f:start(); f:advance(1); f:setTheir({f.partnerInv.items[2]}); f:advance(4); f.root.children.YourOffer.children.Accepted.Visible=true; f:advance(4.5); f:setTheir({f.partnerInv.items[1]}); f.root.children.YourOffer.children.Accepted.Visible=false; f:advance(5); eq(f.declines,1) end)
print("PASS "..passed.." issue4 full P4 runtime tests")
